import{_ as t,o as s,c as l,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/erste-schritte/schueler-aktuelle-schuelerauswahl.png",u="/bilder/erste-schritte/schueler-aktuelle-schuelerauswahl-auswahl-neuaufnahme.png",h="/bilder/erste-schritte/schueler-karteireiter-neuaufnahme.png",d="/bilder/erste-schritte/neuaufnahme-status.png",w=JSON.parse('{"title":"Neue Schülerinnen und Schüler aufnehmen","description":"","frontmatter":{"title":"Neue Schülerinnen und Schüler aufnehmen","source_pageid":357,"source_revision":5486},"headers":[],"relativePath":"einstieg/erste-schritte/neuaufnahmen-in-schild-nrw-tutorial.md","filePath":"einstieg/erste-schritte/neuaufnahmen-in-schild-nrw-tutorial.md"}'),c={name:"einstieg/erste-schritte/neuaufnahmen-in-schild-nrw-tutorial.md"};function o(m,a,p,g,S,f){return s(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="neue-schulerinnen-und-schuler-aufnehmen" tabindex="-1">Neue Schülerinnen und Schüler aufnehmen <a class="header-anchor" href="#neue-schulerinnen-und-schuler-aufnehmen" aria-label="Permalink to &quot;Neue Schülerinnen und Schüler aufnehmen&quot;">​</a></h1><p>Legen Sie neue Schülerdatensätze für das laufende oder das kommende Schuljahr an. Prüfen Sie dabei Aufnahmejahr, Status und die für die Statistik benötigten Angaben.</p><p><a href="/bilder/erste-schritte/schueler-aktuelle-schuelerauswahl.png"><img src="'+i+'" alt="Neuen Schüler anlegen." loading="lazy"></a></p><p><em>Neuen Schüler anlegen.</em></p><p>Richten Sie vor der Neuaufnahme die Schuldaten und die benötigten Katalogeinträge ein. Dazu gehören die Angaben zur <a href="/einstieg/erste-schritte/schule-verwaltung.html">Schule</a> und die <a href="/schild3/unterricht-kataloge/schulbezogene-kataloge-kataloge.html">schulbezogenen Kataloge</a>.</p><h2 id="_1-einen-neuen-datensatz-anlegen" tabindex="-1">1. Einen neuen Datensatz anlegen <a class="header-anchor" href="#_1-einen-neuen-datensatz-anlegen" aria-label="Permalink to &quot;1. Einen neuen Datensatz anlegen&quot;">​</a></h2><p>Klicken Sie in der Leiste unter den Menüpunkten auf das &quot;+ Einfügen&quot;, um einen neuen Schülerdatensatz anzulegen.</p><p><a href="/bilder/erste-schritte/schueler-aktuelle-schuelerauswahl-auswahl-neuaufnahme.png"><img src="'+u+'" alt="Auswahl - aktuelles Schuljahr oder neues Schuljahr." loading="lazy"></a></p><p><em>Auswahl - aktuelles Schuljahr oder neues Schuljahr.</em></p><h2 id="_2-das-aufnahmejahr-wahlen" tabindex="-1">2. Das Aufnahmejahr wählen <a class="header-anchor" href="#_2-das-aufnahmejahr-wahlen" aria-label="Permalink to &quot;2. Das Aufnahmejahr wählen&quot;">​</a></h2><p>Bevor Sie die Daten des Schülers eingeben können, müssen Sie entscheiden, welches Aufnahmejahr dem Schüler zugeordnet werden soll.</p><p>Wird ein Schüler im laufenden Schuljahr aufgenommen, ist das aktuelle Schuljahr zu wählen.</p><p>Sind Sie gerade in der Anmeldephase und geben die Daten aller neu angemeldeten Schüler ein, wählen Sie hier einmal das kommende Schuljahr.</p><p><a href="/bilder/erste-schritte/schueler-karteireiter-neuaufnahme.png"><img src="'+h+'" alt="Eintragen der Schülerdaten" loading="lazy"></a></p><p><em>Eintragen der Schülerdaten</em></p><h2 id="_3-daten-erfassen-und-die-auswahl-prufen" tabindex="-1">3. Daten erfassen und die Auswahl prüfen <a class="header-anchor" href="#_3-daten-erfassen-und-die-auswahl-prufen" aria-label="Permalink to &quot;3. Daten erfassen und die Auswahl prüfen&quot;">​</a></h2><p>In die leeren Registerkarten tragen Sie anschließend die Daten des Schülers ein. Beachten Sie, dass alle Felder mit einem Sternchen relevant für die Statistik-Haupterhebung sind.</p>',17),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Falls Sie neu angelegte Schüler vermissen, prüfen Sie bitte, ob Sie den Karteikasten "),e("em",null,"Neuaufnahme"),n(" in der aktuellen Schülerauswahl ausgewählt haben. Jeder neu angelegte Schüler hat den Status Neuaufnahme und ist nur dann zu sehen, wenn Neuaufnahme mit einem Häkchen versehen ist.")])],-1),r('<h2 id="_4-den-status-zum-schuljahreswechsel-anpassen" tabindex="-1">4. Den Status zum Schuljahreswechsel anpassen <a class="header-anchor" href="#_4-den-status-zum-schuljahreswechsel-anpassen" aria-label="Permalink to &quot;4. Den Status zum Schuljahreswechsel anpassen&quot;">​</a></h2><p>Zum Schuljahreswechsel soll der Status der Schüler, die sich im Februar angemeldet haben, von Neuaufnahme in Aktiv geändert werden. Vor dem Statuswechsel kann schon die Zuordnung zur neuen Klasse vorgenommen werden und ein passendes Informationsschreiben könnte herausgeschickt werden.</p><p><a href="/bilder/erste-schritte/neuaufnahme-status.png"><img src="'+d+'" alt="Ändern des Status der neuen Schüler auf Aktiv." loading="lazy"></a></p><p><em>Ändern des Status der neuen Schüler auf <strong>Aktiv</strong>.</em></p><p>Um den Statuswechsel von <em>Neuaufnahme</em> nach <em>Aktiv</em> durchzuführen, wählen Sie den Karteikasten Neuaufnahme aus, so dass alle neu angelegten Schüler in der aktuellen Schülerauswahl enthalten sind.</p><p>Öffnen Sie den Gruppenprozess <strong>Individualdaten ändern</strong> im Bereich <strong>Allgemeines</strong>. Wählen Sie dort den Status <strong>Aktiv</strong> und führen Sie den Prozess für die angezeigte Gruppe aus.</p><p>Die Schüler sind nun dem Status <em>Aktiv</em> zugeordnet und werden entsprechend in der Standardauswahl im Schülercontainer angezeigt.</p><p>Die Schüler können nun per weiterem Gruppenprozess ihren Einstiegsklassen zugeordnet werden.</p><hr><h2 id="videotutorial" tabindex="-1">Videotutorial <a class="header-anchor" href="#videotutorial" aria-label="Permalink to &quot;Videotutorial&quot;">​</a></h2>',10),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/C6N7sdEIJu0?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Neuaufnahmen_in_Schild-NRW_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5486.")],-1)])])}const _=t(c,[["render",o]]);export{w as __pageData,_ as default};
